        "start_date = \"2026-10-01T09:15:00.000Z\"\n",
        "end_date = \"2026-10-20T15:30:00.000Z\"\n",
        "interval = \"1day\"\n",
        "\n",
        "try:\n",
        "    # Fetch historical data\n",
        "    historical_response = breeze.get_historical_data_v2(\n",
        "        interval=interval,\n",
        "        from_date=start_date,\n",
        "        to_date=end_date,\n",
        "        stock_code=\"RELIND\",\n",
        "        exchange_code=\"NSE\",\n",
        "        product_type=\"cash\"\n",
        "    )\n",
        "\n",
