        "    \"\"\"Runs a single screening, analysis, and execution pass.\"\"\"\n",
        "    print(f\"\\n{'='*70}\\nRUNNING CYCLICAL MARKET MONITORING STEP\\n{'='*70}\")\n",
        "    top_stocks = screen_high_momentum_stocks(breeze)\n",
