        "active_positions_pnl = []\n",
        "\n",
        "if hasattr(risk_manager, 'positions') and risk_manager.positions:\n",
        "    print(\"=== Fetching Real-Time P&L for Active Positions ===\")\n",
        "    for stock, pos in risk_manager.positions.items():\n",
